window.AUTH=window.AUTH||{};window.AUTH["07-1059"]={"d":"07-1059","id":"2008/07-1059","n":"United States v. Eurodif S.A.","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/216256/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-eurodif-sa-usec-inc-v-eurodif-sa-brief-merits","n":77},{"k":"reply","label":"Reply brief for the United States","date":"","url":"https://www.justice.gov/osg/media/216261/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-eurodif-sa-usec-inc-v-eurodif-sa-reply-merits","n":32}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep555/usrep555305/usrep555305.pdf","tr":true,"items":[{"t":"case","label":"B.A. Ballou & Co. v. Citytrust","cite":"591 A.2d 126","y":1991,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/591/126/","by":{"0":"49"}},{"t":"case","label":"Boulware v. United States","cite":"128 S. Ct. 1168","y":2008,"id":"2007/06-1509","sc":1,"sum":"The Court held that a defendant in a criminal tax case does not need to show a contemporaneous intent to treat diversions as returns of capital to demonstrate no taxes were owed. All that mattered, according to the Court, was whether the corporation had earnings or profits and the taxpayer's basis for his stock.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":4,"ar":4,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"17, 18, 22, 23, 32, 43","1":"3, 18"}},{"t":"case","label":"Florida Power & Light Co. v. United States","cite":"307 F.3d 1364","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/307/1364/","op":7,"ar":4,"by":{"0":"16, 17, 26, 27","1":"12, 13"}},{"t":"case","label":"Frank Lyon Co. v. United States","cite":"435 U.S. 561","y":1978,"id":"1977/76-624","sc":1,"op":2,"sum":"Petitioner is entitled to the claimed deductions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Gray v. Powell","cite":"314 U.S. 402","y":1941,"id":"scdb/1941-003","sc":1,"by":{"0":"29, 35"}},{"t":"case","label":"Huffman v. Western Nuclear, Inc.","cite":"486 U.S. 663","y":1988,"id":"1987/87-645","sc":1,"sum":"Section 161(v) does not require DOE to restrict the enrichment of foreign uranium where such restriction would not achieve the statutory goal of \"assur[ing] the maintenance of a viable domestic uranium industry,\" for the statute ties the amount of restriction to be imposed to the achievement of that goal. Pp. 671-674. 825 F. 2d 1430, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Landreth Timber Co. v. Landreth","cite":"471 U.S. 681","y":1985,"id":"1984/83-1961","sc":1,"sum":"The stock at issue here is a \"security\" within the definition of the Acts, United Housing Foundation,Inc. v. Forman, 421 U. S. 837, distinguished, and the \"sale of business\" doctrine does not apply.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Morton v. Ruiz","cite":"415 U.S. 199","y":1974,"id":"1973/72-1052","sc":1,"sum":"Respondent Ruiz and his wife, Papago Indians, left their reservation in Arizona in 1940 to live in an Indian community a few miles away and Ruiz found employment at a nearby mine.. During a prolonged strike, Ruiz applied for but was denied general assistance benefits under the Snyder Act by the Bureau of Indian Affairs (BIA) because of a provision in the BIA Manual limiting eligibility to Indians living \"on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"NSK Ltd . v. United States","cite":"115 F.3d 965","y":1997,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/115/965/","by":{"0":"13, 15"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"op":4,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"16, 17, 44"}},{"t":"case","label":"Pesquera Mares Australes Ltda. v. United States","cite":"266 F.3d 1372","y":2001,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/266/1372/","by":{"0":"24"}},{"t":"case","label":"Powder Co. v. Burkhardt","cite":"97 U.S. 110","y":1878,"id":"scdb/1877-229","sc":1,"op":1,"sum":"This was an action in tbe nature of trover, by tbe Laflin and Rand Powder Company, of New York, against Gottlieb F. Burkhardt, for tbe alleged wrongful conversion of certain acids, glycerine, and other raw materials, bought by him under execution, as tbe property of Carl Dittmar.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48, 49","1":"8"}},{"t":"case","label":"SEC v. National Securities, Inc.","cite":"393 U.S. 453","y":1969,"id":"1968/41","sc":1,"sum":"The Securities and Exchange Commission (SEC) brought suit against respondent National Securities and persons associated with it, alleging violations of § 10 (b) of the Securities Exchange Act and of SEC's Rule 10b-5, arising out of misrepresentations and omissions of material facts in communications sent to shareholders of Producers Life Insurance Co., in an attempt to secure approval of a merger between that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Smiley v. Citibank (S.D.), N. A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":1,"sum":"The Court held that the National Bank Act of 1864 authorizes such charges because a regulation adopted by the Comptroller of the Currency, which defined interest to include late-payment fees, was a reasonable interpretation of the act and entitled to deference.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Sturm v. Boker","cite":"150 U.S. 312","y":1893,"id":"scdb/1893-042","sc":1,"sum":"In 1867 B. and S. entered into a contract which was evidenced by the following writings, signed by them respectively. (1) B. to S., dated September 18: “ Enclosed please find our bill of sundry arms, etc., amounting to $39,887.GO, for which-’amount please give us credit on consignment account. As mutually agreed, we consign these arms to your care, to be shipped to Mexico and to be sold there by you to the best …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"49","1":"8"}},{"t":"case","label":"Techsnabexport v. United States","cite":"515 F. Supp. 2d 1363","y":2007,"court":"Ct. Int’l Trade","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/515/1363/","op":1,"by":{"0":"39"}},{"t":"case","label":"Thai Pineapple Pub. Co. v. United States","cite":"187 F.3d 1362","y":1999,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/187/1362/","by":{"0":"24"}},{"t":"case","label":"United Gas Improvement Co. v. Continental Oil Co.","cite":"381 U.S. 392","y":1965,"id":"1964/644","sc":1,"sum":"Texas Eastern, which operates an interstate natural gas transmission system, agreed with certain producers to purchase for resale in interstate commerce their natural gas production in a substantially developed field with proven reserves. Before the Federal Power Commission (FPC) acted on the examiner's recommendation that certificates be granted, the \"Catco\" case (Public Serv. Comm'n of New York v. FPC, 257 F. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 35","1":"6"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"United States v. Winstar Corp.","cite":"518 U.S. 839","y":1996,"id":"1995/95-865","sc":1,"sum":"In a 7-2 plurality opinion delivered Justice David H. Souter, the Court held that the terms assigning the risk of regulatory change to the Government are enforceable and that the Government is therefore liable in damages for breach, although Congress changed the relevant law, and thereby barred the Government from specifically honoring its agreements.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"sum":"The National Labor Relations Board ordered petitioner to reinstate with back pay an employee found to have been discharged because he gave certain testimony in another proceeding under the National Labor Relations Act. The evidence as to the reason for his discharge was conflicting; and the Board overruled its examiner's findings of fact and his recommendation that the proceedings be dismissed. In decreeing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Zuni Pub. Sch. Dist. No. 89 v. Department of Educ.","cite":"127 S. Ct. 1534","y":2007,"id":"2006/05-1508","sc":1,"sum":"The majority concluded that \"[...] the history of the statute strongly supports the Secretary.\" No member of Congress had expressed an opinion on the formula to be used, so the Department would have been free to calculate the percentiles using either formula.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 828","url":"https://www.law.cornell.edu/uscode/text/15/828","by":{"0":"29"}},{"t":"usc","label":"41 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/41/601","stext":{"head":"§601. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) the term “agency head” means the head and any assistant head of an executive agency, and may “upon the designation by” the head of an executive agency include the chief official of any principal division of the agency;"],[1,"(2) the term “executive agency” means an executive department as defined in section 101 of title 5, an independent establishment as defined by section 104 of title 5 (except that it shall not include the Government Accountability Office), a military department as defined by section 102 of title 5, and a wholly owned Government corporation as defined by section 9101(3) of title 31;"],[1,"(3) the term “contracting officer” means any person who, by appointment in accordance with applicable regulations, has the authority to enter into and administer contracts and make determinations and findings with respect thereto. The term also includes the authorized representative of the contracting officer, acting within the limits of his authority;"],[1,"(4) the term “contractor” means a party to a Government contract other than the Government;"],[1,"(5) the term “Administrator” means the Administrator for Federal Procurement Policy appointed pursuant to the Office of Federal Procurement Policy Act [41 U.S.C. 401 et seq.];"],[1,"(6) the terms “agency board” or “agency board of contract appeals” mean—"],[2,"(A) the Armed Services Board of Contract Appeals established under section 607(a)(1) of this title;"],[2,"(B) the Civilian Board of Contract Appeals established under section 42 of the Office of Federal Procurement Policy Act [41 U.S.C. 438];"],[2,"(C) the board of contract appeals of the Tennessee Valley Authority; or"],[2,"(D) the Postal Service Board of Contract Appeals established under section 607(c) of this title;"],[1,"(7) the term “Armed Services Board” means the Armed Services Board of Contract Appeals established under section 607(a)(1) of this title;"],[1,"(8) the term “Civilian Board” means the Civilian Board of Contract Appeals established under section 42 of the Office of Federal Procurement Policy Act [41 U.S.C. 438]; and"],[1,"(9) the term “misrepresentation of fact” means a false statement of substantive fact, or any conduct which leads to a belief of a substantive fact material to proper understanding of the matter in hand, made with intent to deceive or mislead."]],"more":false,"ed":"2009","src":"https://www.govinfo.gov/link/uscode/41/601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§601. Definitions","tname":"Public Contracts","by":{"0":"16"}},{"t":"usc","label":"41 U.S.C. § 602","url":"https://www.law.cornell.edu/uscode/text/41/602","subs":["(a)"],"stext":{"head":"§602. Applicability of law","paras":[[0,"(a) Executive agency contracts"],[0,"Unless otherwise specifically provided herein, this chapter applies to any express or implied contract (including those of the nonappropriated fund activities described in sections 1346 and 1491 of title 28) entered into by an executive agency for—"],[1,"(1) the procurement of property, other than real property in being;"],[1,"(2) the procurement of services;"],[1,"(3) the procurement of construction, alteration, repair or maintenance of real property; or,"],[1,"(4) the disposal of personal property."],[0,"(b) Tennessee Valley Authority contracts"],[0,"With respect to contracts of the Tennessee Valley Authority, the provisions of this chapter shall apply only to those contracts which contain a disputes clause requiring that a contract dispute be resolved through an agency administrative process. Notwithstanding any other provision of this chapter, contracts of the Tennessee Valley Authority for the sale of fertilizer or electric power or related to the conduct or operation of the electric power system shall be excluded from the chapter."],[0,"(c) Foreign government or international organization contracts"],[0,"This chapter does not apply to a contract with a foreign government, or agency thereof, or international organization, or subsidiary body thereof, if the head of the agency determines that the application of the chapter to the contract would not be in the public interest."]],"more":false,"ed":"2009","src":"https://www.govinfo.gov/link/uscode/41/602?type=usc&year=mostrecent&link-type=html"},"head":"§602. Applicability of law","tname":"Public Contracts","by":{"0":"27","1":"12"}},{"t":"usc","label":"15 U.S.C. § 717","url":"https://www.law.cornell.edu/uscode/text/15/717","by":{"0":"29"}},{"t":"usc","label":"19 U.S.C. § 1677","url":"https://www.law.cornell.edu/uscode/text/19/1677","subs":["(19)","(1)","(2)","(19)(F)","(34)","(35)(A)","(28)"],"stext":{"head":"§1677. Definitions; special rules","paras":[[0,"For purposes of this subtitle—"],[0,"(1) Administering authority"],[1,"The term \"administering authority\" means the Secretary of Commerce, or any other officer of the United States to whom the responsibility for carrying out the duties of the administering authority under this subtitle are transferred by law."],[0,"(2) Commission"],[1,"The term \"Commission\" means the United States International Trade Commission."],[0,"(3) Country"],[1,"The term \"country\" means a foreign country, a political subdivision, dependent territory, or possession of a foreign country, and, except for the purpose of antidumping proceedings, may include an association of 2 or more foreign countries, political subdivisions, dependent territories, or possessions of countries into a customs union outside the United States."],[0,"(4) Industry"],[0,"(A) In general"],[2,"The term \"industry\" means the producers as a whole of a domestic like product, or those producers whose collective output of a domestic like product constitutes a major proportion of the total domestic production of the product."],[0,"(B) Related parties"],[2,"(i) If a producer of a domestic like product and an exporter or importer of the subject merchandise are related parties, or if a producer of the domestic like product is also an importer of the subject merchandise, the producer may, in appropriate circumstances, be excluded from the industry."],[2,"(ii) For purposes of clause (i), a producer and an exporter or importer shall be considered to be related parties, if—"],[3,"(I) the producer directly or indirectly controls the exporter or importer,"],[3,"(II) the exporter or importer directly or indirectly controls the producer,"],[3,"(III) a third party directly or indirectly controls the producer and the exporter or importer, or"],[3,"(IV) the producer and the exporter or importer directly or indirectly control a third party and there is reason to believe that the relationship causes the producer to act differently than a nonrelated producer."],[2,"For purposes of this subparagraph, a party shall be considered to directly or indirectly control another party if the party is legally or operationally in a position to exercise restraint or direction over the other party."],[0,"(C) Regional industries"],[2,"In appropriate circumstances, the United States, for a particular product market, may be divided into 2 or more markets and the producers within each market may be treated as if they were a separate industry if—"],[3,"(i) the producers within such market sell all or almost all of their production of the domestic like product in question in that market, and"],[3,"(ii) the demand in that market is not supplied, to any substantial degree, by producers of the product in question located elsewhere in the United States."],[2,"In such appropriate circumstances, material injury, the threat of material injury, or material retardation of the establishment of an industry may be found to exist with respect to an industry even if the domestic industry as a whole, or those producers whose collective output of a domestic like product constitutes a major proportion of the total domestic production of that product, is not injured, if there is a concentration of dumped imports or imports of merchandise benefiting from a countervailable subsidy into such an isolated market and if the producers of all, or almost all, of the production within that market are being materially injured or threatened by material injury, or if the establishment of an industry is being materially retarded, by reason of the dumped imports or imports of merchandise benefiting from a countervailable subsidy. The term \"regional industry\" means the domestic producers within a region who are treated as a separate industry under this subparagraph."],[0,"(D) Product lines"],[2,"The effect of dumped imports or imports of merchandise benefiting from a countervailable subsidy shall be assessed in relation to the United States production of a domestic like product if available data permit the separate identification of production in terms of such criteria as the production process or the producer's profits. If the domestic production of the domestic like product has no separate identity in terms of such criteria, then the effect of the dumped imports or imports of merchandise benefiting from a countervailable subsidy shall be assessed by the examination of the production of the narrowest group or range of products, which includes a domestic like product, for which the necessary information can be provided."],[0,"(E) Industry producing processed agricultural products"],[0,"(i) In general"],[3,"Subject to clause (v), in an investigation involving a processed agricultural product produced from any raw agricultural product, the producers or growers of the raw agricultural product may be considered part of the industry producing the processed product if—"],[4,"(I) the processed agricultural product is produced from the raw agricultural product through a single continuous line of production; and"],[4,"(II) there is a substantial coincidence of economic interest between the producers or growers of the raw agricultural product and the processors of the processed agricultural product based upon relevant economic factors, which may, in the discretion of the Commission, include price, added market value, or other economic interrelationships (regardless of whether such coincidence of economic interest is based upon any legal relationship)."],[0,"(ii) Processing"],[3,"For purposes of this subparagraph, the processed agricultural product shall be considered to be processed from a raw agricultural product through a single continuous line of production if—"],[4,"(I) the raw agricultural product is substantially or completely devoted to the production of the processed agricultural product; and"],[4,"(II) the processed agricultural product is produced substantially or completely from the raw product."],[0,"(iii) Relevant economic factors"],[3,"For purposes of clause (i)(II), in addition to such other factors it considers relevant to the question of coincidence of economic interest, the Commission shall—"],[4,"(I) if price is taken into account, consider the degree of correlation between the price of the raw agricultural product and the price of the processed agricultural product; and"],[4,"(II) if added market value is taken into account, consider whether the value of the raw agricultural product constitutes a significant percentage of the value of the processed agricultural product."],[0,"(iv) Raw agricultural product"],[3,"For purposes of this subparagraph, the term \"raw agricultural product\" means any farm or fishery product."],[0,"(v) Termination of this subparagraph"],[3,"This subparagraph shall cease to have effect if the United States Trade Representative notifies the administering authority and the Commission that the application of this subparagraph is inconsistent with the international obligations of the United States."],[0,"(5) Countervailable subsidy"],[0,"(A) In general"],[2,"Except as provided in paragraph (5B), a countervailable subsidy is a subsidy described in this paragraph which is specific as described in paragraph (5A)."],[0,"(B) Subsidy described"],[2,"A subsidy is described in this paragraph in the case in which an authority—"],[3,"(i) provides a financial contribution,"],[3,"(ii) provides any form of income or price support within the meaning of Article XVI of the GATT 1994, or"],[3,"(iii) makes a payment to a funding mechanism to provide a financial contribution, or entrusts or directs a private entity to make a financial contribution, if providing the contribution would normally be vested in the government and the practice does not differ in substance from practices normally followed by governments,"],[2,"to a person and a benefit is thereby conferred. For purposes of this paragraph and paragraphs (5A) and (5B), the term \"authority\" means a government of a country or any public entity within the territory of the country."],[0,"(C) Other factors"],[2,"The determination of whether a subsidy exists shall be made without regard to whether the recipient of the subsidy is publicly or privately owned and without regard to whether the subsidy is provided directly or indirectly on the manufacture, production, or export of merchandise. The administering authority is not required to consider the effect of the subsidy in determining whether a subsidy exists under this paragraph."],[0,"(D) Financial contribution"],[2,"The term \"financial contribution\" means—"],[3,"(i) the direct transfer of funds, such as grants, loans, and equity infusions, or the potential direct transfer of funds or liabilities, such as loan guarantees,"],[3,"(ii) foregoing or not collecting revenue that is otherwise due, such as granting tax credits or deductions from taxable income,"],[3,"(iii) providing goods or services, other than general infrastructure, or"],[3,"(iv) purchasing goods."],[0,"(E) Benefit conferred"],[2,"A benefit shall normally be treated as conferred where there is a benefit to the recipient, including—"],[3,"(i) in the case of an equity infusion, if the investment decision is inconsistent with the usual investment practice of private investors, including the practice regarding the provision of risk capital, in the country in which the equity infusion is made,"],[3,"(ii) in the case of a loan, if there is a difference between the amount the recipient of the loan pays on the loan and the amount the recipient would pay on a comparable commercial loan that the recipient could actually obtain on the market,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1677?type=usc&year=mostrecent&link-type=html"},"head":"§1677. Definitions; special rules","tname":"Customs Duties","by":{"0":"31, 3, 19, 23, 4, 31, 31, 2, 3, 3","1":"15"}},{"t":"usc","label":"19 U.S.C. § 1673","url":"https://www.law.cornell.edu/uscode/text/19/1673","subs":["(1)","(2)"],"stext":{"head":"§1673. Antidumping duties imposed","paras":[[0,"If—"],[1,"(1) the administering authority determines that a class or kind of foreign merchandise is being, or is likely to be, sold in the United States at less than its fair value, and"],[1,"(2) the Commission determines that—"],[2,"(A) an industry in the United States—"],[3,"(i) is materially injured, or"],[3,"(ii) is threatened with material injury, or"],[2,"(B) the establishment of an industry in the United States is materially retarded,"],[1,"by reason of imports of that merchandise or by reason of sales (or the likelihood of sales) of that merchandise for importation,"],[0,"then there shall be imposed upon such merchandise an antidumping duty, in addition to any other duty imposed, in an amount equal to the amount by which the normal value exceeds the export price (or the constructed export price) for the merchandise. For purposes of this section and section 1673d(b)(1) of this title, a reference to the sale of foreign merchandise includes the entering into of any leasing arrangement regarding the merchandise that is equivalent to the sale of the merchandise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1673?type=usc&year=mostrecent&link-type=html"},"op":15,"head":"§1673. Antidumping duties imposed","tname":"Customs Duties","by":{"0":"3, 32, passim, 3, 16, 24, 30, 51, 4","1":"8, 12, 14, 23, 1, 2, 4, 8, 16"}},{"t":"usc","label":"19 U.S.C. § 1673a","url":"https://www.law.cornell.edu/uscode/text/19/1673a","subs":["(a)","(a)(1)","(b)","(e)"],"by":{"0":"3, 24, 3, 37"}},{"t":"usc","label":"19 U.S.C. § 1673b","url":"https://www.law.cornell.edu/uscode/text/19/1673b","subs":["(d)(1)(B)","(d)(2)"],"stext":{"head":"§1673b. Preliminary determinations","paras":[[0,"(a) Determination by Commission of reasonable indication of injury"],[0,"(1) General rule"],[1,"Except in the case of a petition dismissed by the administering authority under section 1673a(c)(3) of this title, the Commission, within the time specified in paragraph (2), shall determine, based on the information available to it at the time of the determination, whether there is a reasonable indication that—"],[2,"(A) an industry in the United States—"],[3,"(i) is materially injured, or"],[3,"(ii) is threatened with material injury, or"],[2,"(B) the establishment of an industry in the United States is materially retarded,"],[1,"by reason of imports of the subject merchandise and that imports of the subject merchandise are not negligible. If the Commission finds that imports of the subject merchandise are negligible or otherwise makes a negative determination under this paragraph, the investigation shall be terminated."],[0,"(2) Time for Commission determination"],[1,"The Commission shall make the determination described in paragraph (1)—"],[2,"(A) in the case of a petition filed under section 1673a(b) of this title—"],[3,"(i) within 45 days after the date on which the petition is filed, or"],[3,"(ii) if the time has been extended pursuant to section 1673a(c)(1)(B) of this title, within 25 days after the date on which the Commission receives notice from the administering authority of initiation of the investigation, and"],[2,"(B) in the case of an investigation initiated under section 1673a(a) of this title, within 45 days after the date on which the Commission receives notice from the administering authority that an investigation has been initiated under such section."],[0,"(b) Preliminary determination by administering authority"],[0,"(1) Period of antidumping duty investigation"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), within 140 days after the date on which the administering authority initiates an investigation under section 1673a(c) of this title, or an investigation is initiated under section 1673a(a) of this title, but not before an affirmative determination by the Commission under subsection (a) of this section, the administering authority shall make a determination, based upon the information available to it at the time of the determination, of whether there is a reasonable basis to believe or suspect that the merchandise is being sold, or is likely to be sold, at less than fair value."],[0,"(B) If certain short life cycle merchandise involved"],[2,"If a petition filed under section 1673a(b) of this title, or an investigation initiated under section 1673a(a) of this title, concerns short life cycle merchandise that is included in a product category established under section 1673h(a) of this title, subparagraph (A) shall be applied—"],[3,"(i) by substituting \"100 days\" for \"140 days\" if manufacturers that are second offenders account for a significant proportion of the merchandise under investigation, and"],[3,"(ii) by substituting \"80 days\" for \"140 days\" if manufacturers that are multiple offenders account for a significant proportion of the merchandise under investigation."],[0,"(C) Definitions of offenders"],[2,"For purposes of subparagraph (B)—"],[3,"(i) The term \"second offender\" means a manufacturer that is specified in 2 affirmative dumping determinations (within the meaning of section 1673h of this title) as the manufacturer of short life cycle merchandise that is—"],[4,"(I) specified in both such determinations, and"],[4,"(II) within the scope of the product category referred to in subparagraph (B)."],[3,"(ii) The term \"multiple offender\" means a manufacturer that is specified in 3 or more affirmative dumping determinations (within the meaning of section 1673h of this title) as the manufacturer of short life cycle merchandise that is—"],[4,"(I) specified in each of such determinations, and"],[4,"(II) within the scope of the product category referred to in subparagraph (B)."],[0,"(2) Preliminary determination under waiver of verification"],[1,"Within 75 days after the initiation of an investigation, the administering authority shall cause an official designated for such purpose to review the information concerning the case received during the first 60 days of the investigation, and, if there appears to be sufficient information available upon which the preliminary determination can reasonably be based, to disclose to the petitioner and any interested party, then a party to the proceedings that requests such disclosure, all available nonconfidential information and all other information which is disclosed pursuant to section 1677f of this title. Within 3 days (not counting Saturdays, Sundays, or legal public holidays) after such disclosure, the petitioner and each party which is an interested party described in subparagraph (C), (D), (E), (F), or (G) of section 1677(9) of this title to whom such disclosure was made may furnish to the administering authority an irrevocable written waiver of verification of the information received by the authority, and an agreement that it is willing to have a preliminary determination made on the basis of the record then available to the authority. If a timely waiver and agreement have been received from the petitioner and each party which is an interested party described in subparagraph (C), (D), (E), (F), or (G) of section 1677(9) of this title to whom the disclosure was made, and the authority finds that sufficient information is then available upon which the preliminary determination can reasonably be based, a preliminary determination shall be made within 90 days after the initiation of the investigation on the basis of the record established during the first 60 days after the investigation was initiated."],[0,"(3) De minimis dumping margin"],[1,"In making a determination under this subsection, the administering authority shall disregard any weighted average dumping margin that is de minimis. For purposes of the preceding sentence, a weighted average dumping margin is de minimis if the administering authority determines that it is less than 2 percent ad valorem or the equivalent specific rate for the subject merchandise."],[0,"(c) Extension of period in extraordinarily complicated cases"],[0,"(1) In general"],[1,"If—"],[2,"(A) the petitioner makes a timely request for an extension of the period within which the determination must be made under subsection (b)(1), or"],[2,"(B) the administering authority concludes that the parties concerned are cooperating and determines that—"],[3,"(i) the case is extraordinarily complicated by reason of—"],[4,"(I) the number and complexity of the transactions to be investigated or adjustments to be considered,"],[4,"(II) the novelty of the issues presented, or"],[4,"(III) the number of firms whose activities must be investigated, and"],[3,"(ii) additional time is necessary to make the preliminary determination,"],[1,"then the administering authority may postpone making the preliminary determination under subsection (b)(1) until not later than the 190th day after the date on which the administering authority initiates an investigation under section 1673a(c) of this title, or an investigation is initiated under section 1673a(a) of this title. No extension of a determination date may be made under this paragraph for any investigation in which a determination date provided for in subsection (b)(1)(B) applies unless the petitioner submits written notice to the administering authority of its consent to the extension."],[0,"(2) Notice of postponement"],[1,"The administering authority shall notify the parties to the investigation, not later than 20 days before the date on which the preliminary determination would otherwise be required under subsection (b)(1), if it intends to postpone making the preliminary determination under paragraph (1). The notification shall include an explanation of the reasons for the postponement, and notice of the postponement shall be published in the Federal Register."],[0,"(d) Effect of determination by the administering authority"],[0,"If the preliminary determination of the administering authority under subsection (b) of this section is affirmative, the administering authority—"],[1,"(1)(A) shall—"],[2,"(i) determine an estimated weighted average dumping margin for each exporter and producer individually investigated, and"],[2,"(ii) determine, in accordance with section 1673d(c)(5) of this title, an estimated all-others rate for all exporters and producers not individually investigated, and"],[1,"(B) shall order the posting of a cash deposit, bond, or other security, as the administering authority deems appropriate, for each entry of the subject merchandise in an amount based on the estimated weighted average dumping margin or the estimated all-others rate, whichever is applicable,"],[1,"(2) shall order the suspension of liquidation of all entries of merchandise subject to the determination which are entered, or withdrawn from warehouse, for consumption on or after the later of—"],[2,"(A) the date on which notice of the determination is published in the Federal Register, or"],[2,"(B) the date that is 60 days after the date on which notice of the determination to initiate the investigation is published in the Federal Register, and"],[1,"(3) shall make available to the Commission all information upon which such determination was based and which the Commission considers relevant to its injury determination, under such procedures as the administering authority and the Commission may establish to prevent disclosure, other than with the consent of the party providing it or under protective order, of any information to which confidential treatment has been given by the administering authority."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1673b?type=usc&year=mostrecent&link-type=html"},"head":"§1673b. Preliminary determinations","tname":"Customs Duties","by":{"0":"36, 36","1":"19, 19"}},{"t":"usc","label":"19 U.S.C. § 1673c","url":"https://www.law.cornell.edu/uscode/text/19/1673c","subs":["(c)"],"by":{"0":"39"}},{"t":"usc","label":"19 U.S.C. § 1673d","url":"https://www.law.cornell.edu/uscode/text/19/1673d","subs":["(a)(1)","(c)(2)"],"by":{"0":"24, 4, 24"}},{"t":"usc","label":"19 U.S.C. § 1673e","url":"https://www.law.cornell.edu/uscode/text/19/1673e","subs":["(a)","(a)(1)"],"by":{"0":"3, 4, 24"}},{"t":"usc","label":"19 U.S.C. § 1677a","url":"https://www.law.cornell.edu/uscode/text/19/1677a","subs":["(a)","(b)","(e)","(d)(2)"],"stext":{"head":"§1677a. Export price and constructed export price","paras":[[0,"(a) Export price"],[0,"The term \"export price\" means the price at which the subject merchandise is first sold (or agreed to be sold) before the date of importation by the producer or exporter of the subject merchandise outside of the United States to an unaffiliated purchaser in the United States or to an unaffiliated purchaser for exportation to the United States, as adjusted under subsection (c)."],[0,"(b) Constructed export price"],[0,"The term \"constructed export price\" means the price at which the subject merchandise is first sold (or agreed to be sold) in the United States before or after the date of importation by or for the account of the producer or exporter of such merchandise or by a seller affiliated with the producer or exporter, to a purchaser not affiliated with the producer or exporter, as adjusted under subsections (c) and (d)."],[0,"(c) Adjustments for export price and constructed export price"],[0,"The price used to establish export price and constructed export price shall be—"],[1,"(1) increased by—"],[2,"(A) when not included in such price, the cost of all containers and coverings and all other costs, charges, and expenses incident to placing the subject merchandise in condition packed ready for shipment to the United States,"],[2,"(B) the amount of any import duties imposed by the country of exportation which have been rebated, or which have not been collected, by reason of the exportation of the subject merchandise to the United States, and"],[2,"(C) the amount of any countervailing duty imposed on the subject merchandise under part I of this subtitle to offset an export subsidy, and"],[1,"(2) reduced by—"],[2,"(A) except as provided in paragraph (1)(C), the amount, if any, included in such price, attributable to any additional costs, charges, or expenses, and United States import duties, which are incident to bringing the subject merchandise from the original place of shipment in the exporting country to the place of delivery in the United States, and"],[2,"(B) the amount, if included in such price, of any export tax, duty, or other charge imposed by the exporting country on the exportation of the subject merchandise to the United States, other than an export tax, duty, or other charge described in section 1677(6)(C) of this title."],[0,"(d) Additional adjustments to constructed export price"],[0,"For purposes of this section, the price used to establish constructed export price shall also be reduced by—"],[1,"(1) the amount of any of the following expenses generally incurred by or for the account of the producer or exporter, or the affiliated seller in the United States, in selling the subject merchandise (or subject merchandise to which value has been added)—"],[2,"(A) commissions for selling the subject merchandise in the United States;"],[2,"(B) expenses that result from, and bear a direct relationship to, the sale, such as credit expenses, guarantees and warranties;"],[2,"(C) any selling expenses that the seller pays on behalf of the purchaser; and"],[2,"(D) any selling expenses not deducted under subparagraph (A), (B), or (C);"],[1,"(2) the cost of any further manufacture or assembly (including additional material and labor), except in circumstances described in subsection (e); and"],[1,"(3) the profit allocated to the expenses described in paragraphs (1) and (2)."],[0,"(e) Special rule for merchandise with value added after importation"],[0,"Where the subject merchandise is imported by a person affiliated with the exporter or producer, and the value added in the United States by the affiliated person is likely to exceed substantially the value of the subject merchandise, the administering authority shall determine the constructed export price for such merchandise by using one of the following prices if there is a sufficient quantity of sales to provide a reasonable basis for comparison and the administering authority determines that the use of such sales is appropriate:"],[1,"(1) The price of identical subject merchandise sold by the exporter or producer to an unaffiliated person."],[1,"(2) The price of other subject merchandise sold by the exporter or producer to an unaffiliated person."],[0,"If there is not a sufficient quantity of sales to provide a reasonable basis for comparison under paragraph (1) or (2), or the administering authority determines that neither of the prices described in such paragraphs is appropriate, then the constructed export price may be determined on any other reasonable basis."],[0,"(f) Special rule for determining profit"],[0,"(1) In general"],[1,"For purposes of subsection (d)(3), profit shall be an amount determined by multiplying the total actual profit by the applicable percentage."],[0,"(2) Definitions"],[1,"For purposes of this subsection:"],[0,"(A) Applicable percentage"],[2,"The term \"applicable percentage\" means the percentage determined by dividing the total United States expenses by the total expenses."],[0,"(B) Total United States expenses"],[2,"The term \"total United States expenses\" means the total expenses described in subsection (d)(1) and (2)."],[0,"(C) Total expenses"],[2,"The term \"total expenses\" means all expenses in the first of the following categories which applies and which are incurred by or on behalf of the foreign producer and foreign exporter of the subject merchandise and by or on behalf of the United States seller affiliated with the producer or exporter with respect to the production and sale of such merchandise:"],[3,"(i) The expenses incurred with respect to the subject merchandise sold in the United States and the foreign like product sold in the exporting country if such expenses were requested by the administering authority for the purpose of establishing normal value and constructed export price."],[3,"(ii) The expenses incurred with respect to the narrowest category of merchandise sold in the United States and the exporting country which includes the subject merchandise."],[3,"(iii) The expenses incurred with respect to the narrowest category of merchandise sold in all countries which includes the subject merchandise."],[0,"(D) Total actual profit"],[2,"The term \"total actual profit\" means the total profit earned by the foreign producer, exporter, and affiliated parties described in subparagraph (C) with respect to the sale of the same merchandise for which total expenses are determined under such subparagraph."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1677a?type=usc&year=mostrecent&link-type=html"},"head":"§1677a. Export price and constructed export price","tname":"Customs Duties","by":{"0":"3, 42, 42, 37, 42","1":"14, 15, 15, 15, 20, 20"}},{"t":"usc","label":"19 U.S.C. § 1677b","url":"https://www.law.cornell.edu/uscode/text/19/1677b","subs":["(a)(1)(B)","(a)(1)(C)","(a)(4)","(c)(1)","(c)(2)","(e)","(e)(1)"],"stext":{"head":"§1677b. Normal value","paras":[[0,"(a) Determination"],[0,"In determining under this subtitle whether subject merchandise is being, or is likely to be, sold at less than fair value, a fair comparison shall be made between the export price or constructed export price and normal value. In order to achieve a fair comparison with the export price or constructed export price, normal value shall be determined as follows:"],[0,"(1) Determination of normal value"],[0,"(A) In general"],[2,"The normal value of the subject merchandise shall be the price described in subparagraph (B), at a time reasonably corresponding to the time of the sale used to determine the export price or constructed export price under section 1677a(a) or (b) of this title."],[0,"(B) Price"],[2,"The price referred to in subparagraph (A) is—"],[3,"(i) the price at which the foreign like product is first sold (or, in the absence of a sale, offered for sale) for consumption in the exporting country, in the usual commercial quantities and in the ordinary course of trade and, to the extent practicable, at the same level of trade as the export price or constructed export price, or"],[3,"(ii) in a case to which subparagraph (C) applies, the price at which the foreign like product is so sold (or offered for sale) for consumption in a country other than the exporting country or the United States, if—"],[4,"(I) such price is representative,"],[4,"(II) the aggregate quantity (or, if quantity is not appropriate, value) of the foreign like product sold by the exporter or producer in such other country is 5 percent or more of the aggregate quantity (or value) of the subject merchandise sold in the United States or for export to the United States, and"],[4,"(III) the administering authority does not determine that the particular market situation prevents a proper comparison with the export price or constructed export price."],[0,"(C) Third country sales"],[2,"This subparagraph applies when—"],[3,"(i) the foreign like product is not sold (or offered for sale) for consumption in the exporting country as described in subparagraph (B)(i),"],[3,"(ii) the administering authority determines that the aggregate quantity (or, if quantity is not appropriate, value) of the foreign like product sold in the exporting country is insufficient to permit a proper comparison with the sales of the subject merchandise to the United States, or"],[3,"(iii) the particular market situation in the exporting country does not permit a proper comparison with the export price or constructed export price."],[2,"For purposes of clause (ii), the aggregate quantity (or value) of the foreign like product sold in the exporting country shall normally be considered to be insufficient if such quantity (or value) is less than 5 percent of the aggregate quantity (or value) of sales of the subject merchandise to the United States."],[0,"(2) Fictitious markets"],[1,"No pretended sale or offer for sale, and no sale or offer for sale intended to establish a fictitious market, shall be taken into account in determining normal value. The occurrence of different movements in the prices at which different forms of the foreign like product are sold (or, in the absence of sales, offered for sale) in the exporting country after the issuance of an antidumping duty order may be considered by the administering authority as evidence of the establishment of a fictitious market for the foreign like product if the movement in such prices appears to reduce the amount by which the normal value exceeds the export price (or the constructed export price) of the subject merchandise."],[0,"(3) Exportation from an intermediate country"],[1,"Where the subject merchandise is exported to the United States from an intermediate country, normal value shall be determined in the intermediate country, except that normal value may be determined in the country of origin of the subject merchandise if—"],[2,"(A) the producer knew at the time of the sale that the subject merchandise was destined for exportation;"],[2,"(B) the subject merchandise is merely transshipped through the intermediate country;"],[2,"(C) sales of the foreign like product in the intermediate country do not satisfy the conditions of paragraph (1)(C); or"],[2,"(D) the foreign like product is not produced in the intermediate country."],[0,"(4) Use of constructed value"],[1,"If the administering authority determines that the normal value of the subject merchandise cannot be determined under paragraph (1)(B)(i), then, notwithstanding paragraph (1)(B)(ii), the normal value of the subject merchandise may be the constructed value of that merchandise, as determined under subsection (e)."],[0,"(5) Indirect sales or offers for sale"],[1,"If the foreign like product is sold or, in the absence of sales, offered for sale through an affiliated party, the prices at which the foreign like product is sold (or offered for sale) by such affiliated party may be used in determining normal value."],[0,"(6) Adjustments"],[1,"The price described in paragraph (1)(B) shall be—"],[2,"(A) increased by the cost of all containers and coverings and all other costs, charges, and expenses incident to placing the subject merchandise in condition packed ready for shipment to the United States;"],[2,"(B) reduced by—"],[3,"(i) when included in the price described in paragraph (1)(B), the cost of all containers and coverings and all other costs, charges, and expenses incident to placing the foreign like product in condition packed ready for shipment to the place of delivery to the purchaser,"],[3,"(ii) the amount, if any, included in the price described in paragraph (1)(B), attributable to any additional costs, charges, and expenses incident to bringing the foreign like product from the original place of shipment to the place of delivery to the purchaser, and"],[3,"(iii) the amount of any taxes imposed directly upon the foreign like product or components thereof which have been rebated, or which have not been collected, on the subject merchandise, but only to the extent that such taxes are added to or included in the price of the foreign like product, and"],[2,"(C) increased or decreased by the amount of any difference (or lack thereof) between the export price or constructed export price and the price described in paragraph (1)(B) (other than a difference for which allowance is otherwise provided under this section) that is established to the satisfaction of the administering authority to be wholly or partly due to—"],[3,"(i) the fact that the quantities in which the subject merchandise is sold or agreed to be sold to the United States are greater than or less than the quantities in which the foreign like product is sold, agreed to be sold, or offered for sale,"],[3,"(ii) the fact that merchandise described in subparagraph (B) or (C) of section 1677(16) of this title is used in determining normal value, or"],[3,"(iii) other differences in the circumstances of sale."],[0,"(7) Additional adjustments"],[0,"(A) Level of trade"],[2,"The price described in paragraph (1)(B) shall also be increased or decreased to make due allowance for any difference (or lack thereof) between the export price or constructed export price and the price described in paragraph (1)(B) (other than a difference for which allowance is otherwise made under this section) that is shown to be wholly or partly due to a difference in level of trade between the export price or constructed export price and normal value, if the difference in level of trade—"],[3,"(i) involves the performance of different selling activities; and"],[3,"(ii) is demonstrated to affect price comparability, based on a pattern of consistent price differences between sales at different levels of trade in the country in which normal value is determined."],[2,"In a case described in the preceding sentence, the amount of the adjustment shall be based on the price differences between the two levels of trade in the country in which normal value is determined."],[0,"(B) Constructed export price offset"],[2,"When normal value is established at a level of trade which constitutes a more advanced stage of distribution than the level of trade of the constructed export price, but the data available do not provide an appropriate basis to determine under subparagraph (A)(ii) a level of trade adjustment, normal value shall be reduced by the amount of indirect selling expenses incurred in the country in which normal value is determined on sales of the foreign like product but not more than the amount of such expenses for which a deduction is made under section 1677a(d)(1)(D) of this title."],[0,"(8) Adjustments to constructed value"],[1,"Constructed value as determined under subsection (e), may be adjusted, as appropriate, pursuant to this subsection."],[0,"(b) Sales at less than cost of production"],[0,"(1) Determination; sales disregarded"],[1,"Whenever the administering authority has reasonable grounds to believe or suspect that sales of the foreign like product under consideration for the determination of normal value have been made at prices which represent less than the cost of production of that product, the administering authority shall determine whether, in fact, such sales were made at less than the cost of production. If the administering authority determines that sales made at less than the cost of production—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1677b?type=usc&year=mostrecent&link-type=html"},"head":"§1677b. Normal value","tname":"Customs Duties","by":{"0":"3, 43, 43, 43, 43, 43, 43, 33","1":"14, 15"}},{"t":"law","label":"Pub. L. No. 96-39","url":"https://www.govinfo.gov/link/statute/93/150","by":{"0":"32"}},{"t":"law","label":"Pub. L. No. 98-573","url":"https://www.govinfo.gov/link/statute/98/3024","by":{"0":"30"}},{"t":"usc","label":"42 U.S.C. § 2297h","url":"https://www.law.cornell.edu/uscode/text/42/2297h","by":{"0":"6"}},{"t":"usc","label":"19 U.S.C. § 1516a","url":"https://www.law.cornell.edu/uscode/text/19/1516a","subs":["(a)(2)","(b)(1)(B)(i)"],"by":{"0":"4, 4, 24"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(d)"],"by":{"0":"15"}},{"t":"usc","label":"28 U.S.C. § 1581","url":"https://www.law.cornell.edu/uscode/text/28/1581","subs":["(c)"],"by":{"0":"4"}},{"t":"reg","label":"19 C.F.R. § 351.401","url":"https://www.ecfr.gov/current/title-19/section-351.401","subs":["(a)","(h)"],"by":{"0":"10, 40, 9, 10, 39, 41"}},{"t":"reg","label":"73 Fed. Reg. 16,517","url":"https://www.govinfo.gov/link/fr/73/16517","by":{"0":"9, 40","1":"14, 18"}},{"t":"reg","label":"Final Results of Five-Year Sunset Review of Suspended Antidumping Duty Investigation on Uranium from the Russian Federation, 71 Fed. Reg. 32,517","url":"https://www.govinfo.gov/link/fr/71/32517","by":{"0":"38, 39"}},{"t":"reg","label":"Low Enriched Uranium from France, 67 Fed. Reg. 6680","url":"https://www.govinfo.gov/link/fr/67/6680","by":{"0":"12"}},{"t":"reg","label":"Low Enriched Uranium From France, Germany, the Netherlands, and the United Kingdom, 66 Fed. Reg. 1080","url":"https://www.govinfo.gov/link/fr/66/1080","by":{"0":"6"}},{"t":"reg","label":"Low Enriched Uranium from the United Kingdom, Germany, and the Netherlands, 66 Fed. Reg. 65,886","url":"https://www.govinfo.gov/link/fr/66/65886","by":{"0":"12"}},{"t":"reg","label":"Uranium from Kazakhstan, Kyrgyzstan, Russia, Tajikistan, Ukraine, and Uzbekistan, 57 Fed. Reg. 49,220","url":"https://www.govinfo.gov/link/fr/57/49220","by":{"0":"38"}},{"t":"case","label":"Barsebäck Kraft AB v. United States","cite":"36 Fed. Cl. 691","y":1996,"url":"https://www.courtlistener.com/c/Fed.%20Cl./36/691/","by":{"1":"12"}},{"t":"case","label":"Centerior Serv. Co. v. United States","cite":"1997 U.S. Claims LEXIS 323","y":1997,"court":"Fed. Cl. Dec. 29","by":{"1":"12"}},{"t":"case","label":"Corus Staal BV v. Department of Commerce","cite":"395 F.3d 1343","y":2005,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/395/1343/","by":{"1":"23"}},{"t":"case","label":"First Comics, Inc. v. World Color Press, Inc.","cite":"884 F.2d 1033","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/884/1033/","op":2,"ar":6,"by":{"1":"13"}},{"t":"case","label":"INS v. Yueh-Shaio Yang","cite":"519 U.S. 26","y":1996,"id":"1996/95-938","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that in deciding whether to grant a waiver under the Immigration and Nationality Act, the Attorney General or her delegate, the Immigration and Naturalization Service, may take into account acts of fraud committed by the alien in connection to his entry into the United States.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"law","label":"Pub. L. No. 110-329","url":"https://www.govinfo.gov/link/plaw/110/public/329","by":{"1":"21"}},{"t":"usc","label":"15 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/15/13","subs":["(a)"],"by":{"1":"13"}},{"t":"usc","label":"19 U.S.C. § 3501","url":"https://www.law.cornell.edu/uscode/text/19/3501","by":{"1":"23"}},{"t":"usc","label":"19 U.S.C. § 3512","url":"https://www.law.cornell.edu/uscode/text/19/3512","subs":["(a)(1)","(c)(1)"],"by":{"1":"23, 23"}},{"t":"usc","label":"19 U.S.C. § 1677j","url":"https://www.law.cornell.edu/uscode/text/19/1677j","subs":["(a)"],"by":{"1":"20, 20"}},{"t":"usc","label":"42 U.S.C. § 3112A","url":"https://www.law.cornell.edu/uscode/text/42/3112A","by":{"1":"21"}},{"t":"reg","label":"Uranium from Kazakhstan, Kyrgyzstan, Russia, Tajikistan, Ukraine, and Uzbekistan, 57 Fed. Reg. 49,235","url":"https://www.govinfo.gov/link/fr/57/49235","by":{"1":"21"}}]};